import * as React from "react";
import { Tooltip } from '../tooltip';
import { MpaIcon } from "../icon";

type SortDirection = "asc" | "desc" | null;
export interface HeaderProps {
  headers: { 
    sequence: string; 
    displayName: string; 
    tooltipText?: string; 
    align?: "left" | "right" | "center"; 
    width?: string;
    isEditable?: boolean;
    isEditorType? : "text" | "date" | "dropdown" | "switch";
    dropdownOptions?: { label: string; value: string }[];
    isSortable?: boolean;
    sortDirection?: SortDirection;
  }[];
  onSortAction?: (sequence: string, direction: Exclude<SortDirection, null>) => void;
}

const Header: React.FC<HeaderProps> = ({headers,onSortAction}) => {

   const handleSortClick = (header: typeof headers[number]) => {
      if (!header.isSortable) return;
      let nextDirection: "asc" | "desc";
      if (header.sortDirection === "asc") {
        nextDirection = "desc";
      } else if (header.sortDirection === "desc") {
        nextDirection = "asc";
      } else {
        nextDirection = "desc";
      }      
      onSortAction?.(header.sequence, nextDirection);
  };

  return (
    <>
    {headers.map((header, index) => (
      <th
        key={index}
        style={{ textAlign: header.align, width: header.width }}
        onClick={() => header.isSortable && handleSortClick(header)}
        className={header.isSortable ? "sortable-header" : "unsortable-header"}
      >
        <div className="header-cell-content">
          {header.tooltipText ? (
            <Tooltip tooltipText={String(header.tooltipText)} tooltipPlacement="right">
              {header.displayName}
            </Tooltip>
          ) : (
            <span>{header.displayName}</span>
          )}

          {header.isSortable && (
            <span className="sort-indicator" aria-label={`Sort by ${header.displayName}`}>
              {header.sortDirection === "asc" && (
                <span className="sort-icon">
                  <MpaIcon iconName="CaretUp_Filled" />
                </span>
              )}
              {header.sortDirection === "desc" && (
                <span className="sort-icon">
                  <MpaIcon iconName="CaretDown_Filled" />
                </span>
              )}
              {!header.sortDirection && (
                <>
                  <span className="sort-icon">
                    <MpaIcon iconName="CaretUp_Filled" />
                  </span>
                  <span className="sort-icon">
                    <MpaIcon iconName="CaretDown_Filled" />
                  </span>
                </>
              )}
            </span>
          )}
        </div>
      </th>      
    ))}      
    </>
  );
};

export default Header;
